fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Consider first n participants (or fewer if participations shorter)
    let eligible_count = participations
        .iter()
        .take(n as usize)
        .filter(|&&attendance| {
            // Check if participant can attend at least k more sessions
            5u8.saturating_sub(attendance) >= k
        })
        .count() as u8;

    // Maximum teams is eligible_count divided by 3
    eligible_count / 3
}